'use client'

import * as React from 'react'

import './aurora-backdrop.css'

export type AuroraBackdropProps = React.ComponentPropsWithoutRef<'div'> & {
    /** Up to four CSS colors for the glow. */
    colors?: string[]
    /** Seconds for one full drift cycle. Higher is calmer. */
    speed?: number
    /** Blur radius of the glow, in px. */
    blur?: number
    /** Opacity of the glow layer, 0–1. */
    intensity?: number
    /** Stop the drift. Wire this to a visible pause control on pages where the backdrop runs for long. */
    paused?: boolean
}

const DEFAULT_COLORS = ['#22d3ee', '#a78bfa', '#34d399', '#f472b6']

const AuroraBackdrop = React.forwardRef<HTMLDivElement, AuroraBackdropProps>(({
    colors = DEFAULT_COLORS,
    speed = 20,
    blur = 64,
    intensity = 0.55,
    paused = false,
    className,
    style,
    children,
    ...props
}, forwardedRef) => {
    const localRef = React.useRef<HTMLDivElement | null>(null)
    const [offscreen, setOffscreen] = React.useState(false)

    const setRef = React.useCallback((node: HTMLDivElement | null) => {
        localRef.current = node
        if (typeof forwardedRef === 'function') forwardedRef(node)
        else if (forwardedRef) forwardedRef.current = node
    }, [forwardedRef])

    // Don't spend GPU time on a backdrop nobody can see.
    React.useEffect(() => {
        const node = localRef.current
        if (!node || typeof IntersectionObserver === 'undefined') return
        const observer = new IntersectionObserver(([entry]) => setOffscreen(!entry.isIntersecting))
        observer.observe(node)
        return () => observer.disconnect()
    }, [])

    const palette = colors.length ? colors : DEFAULT_COLORS
    const colorVars = Object.fromEntries(
        Array.from({ length: 4 }, (_, i) => [`--rad-fx-aurora-color-${i + 1}`, palette[i % palette.length]])
    )

    return <div
        ref={setRef}
        className={['rad-fx-aurora', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{
            ...colorVars,
            '--rad-fx-aurora-speed': `${speed}s`,
            '--rad-fx-aurora-blur': `${blur}px`,
            '--rad-fx-aurora-intensity': intensity,
            ...style
        } as React.CSSProperties}
        {...props}
    >
        {/* Purely decorative: hidden from assistive tech and from pointer events. */}
        <div className="rad-fx-aurora-glow" aria-hidden="true">
            <span className="rad-fx-aurora-blob" />
            <span className="rad-fx-aurora-blob" />
            <span className="rad-fx-aurora-blob" />
            <span className="rad-fx-aurora-blob" />
        </div>
        <div className="rad-fx-aurora-content">{children}</div>
    </div>
})

AuroraBackdrop.displayName = 'AuroraBackdrop'

export default AuroraBackdrop

/* AuroraBackdrop: soft colour blobs drifting behind content. */
.rad-fx-aurora {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-aurora-glow {
    position: absolute;
    inset: -20%;
    z-index: -1;
    pointer-events: none;
    opacity: var(--rad-fx-aurora-intensity, 0.55);
    filter: blur(var(--rad-fx-aurora-blur, 64px));
}

.rad-fx-aurora-blob {
    position: absolute;
    width: 55%;
    aspect-ratio: 1;
    border-radius: 50%;
    animation: rad-fx-aurora-drift var(--rad-fx-aurora-speed, 20s) ease-in-out infinite alternate;
    will-change: transform;
}

.rad-fx-aurora-blob:nth-child(1) { top: 0; left: 0; background: var(--rad-fx-aurora-color-1); }
.rad-fx-aurora-blob:nth-child(2) { top: 10%; right: 0; background: var(--rad-fx-aurora-color-2); animation-delay: calc(var(--rad-fx-aurora-speed, 20s) / -4); }
.rad-fx-aurora-blob:nth-child(3) { bottom: 0; left: 15%; background: var(--rad-fx-aurora-color-3); animation-delay: calc(var(--rad-fx-aurora-speed, 20s) / -2); }
.rad-fx-aurora-blob:nth-child(4) { bottom: 5%; right: 15%; background: var(--rad-fx-aurora-color-4); animation-delay: calc(var(--rad-fx-aurora-speed, 20s) * -0.75); }

.rad-fx-aurora[data-state='paused'] .rad-fx-aurora-blob {
    animation-play-state: paused;
}

.rad-fx-aurora-content {
    position: relative;
}

@keyframes rad-fx-aurora-drift {
    0% { transform: translate(0, 0) rotate(0deg) scale(1); }
    50% { transform: translate(18%, 12%) rotate(60deg) scale(1.15); }
    100% { transform: translate(-12%, 20%) rotate(120deg) scale(0.9); }
}

/* Reduced motion: keep the colours, drop the drift.
   Applies to the OS setting, or to an in-app setting via data-rad-fx-motion="reduce" on any ancestor. */
@media (prefers-reduced-motion: reduce) {
    .rad-fx-aurora-blob {
        animation: none;
    }
}

[data-rad-fx-motion='reduce'] .rad-fx-aurora-blob {
    animation: none;
}
